import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE_ASSET = '자산 담당자';
const ROLE_ACCOUNTING = '예산·회계 담당자';
// 가정: 등록 시 사용 여부를 보내지 않으면 '사용'으로 저장한다.
const DEFAULT_USE_STATUS = '사용';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const NUM_RE = /^-?\d+(\.\d+)?$/;
const INT_RE = /^\d+$/;

interface AssetValues {
  assetName: string | null;
  acquisitionDate: string | null;
  acquisitionCost: string | null;
  isDepreciable: boolean | null;
  depreciationMethod: string | null;
  usefulLifeYears: string | null;
  depreciationStartDate: string | null;
  useStatus: string | null;
}

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_FIXED_ASSET_INPUT', message);
}

function text(v: unknown): string | null {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function boolOf(v: unknown): boolean | null {
  if (v === undefined || v === null || v === '') return null;
  if (v === true || v === 'true') return true;
  if (v === false || v === 'false') return false;
  throw invalid('상각 여부 형식이 올바르지 않습니다.');
}

function validateAsset(v: AssetValues): void {
  const missing: string[] = [];
  if (!v.assetName) missing.push('자산명');
  if (!v.acquisitionDate) missing.push('취득일');
  if (!v.acquisitionCost) missing.push('취득원가');
  if (v.isDepreciable === null) missing.push('상각 여부');
  if (v.isDepreciable === true) {
    if (!v.depreciationMethod) missing.push('상각 방법');
    if (!v.usefulLifeYears) missing.push('내용연수');
    if (!v.depreciationStartDate) missing.push('상각 시작일');
  }
  if (missing.length > 0) {
    throw invalid('필수 항목이 누락되었습니다: ' + missing.join(', '));
  }
  if ((v.assetName as string).length > 200) {
    throw invalid('자산명은 200자 이하여야 합니다.');
  }
  if (!DATE_RE.test(v.acquisitionDate as string)) {
    throw invalid('취득일 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  if (!NUM_RE.test(v.acquisitionCost as string)) {
    throw invalid('취득원가 금액 형식이 올바르지 않습니다.');
  }
  if (Number(v.acquisitionCost) < 0) {
    throw invalid('취득원가는 0 이상이어야 합니다.');
  }
  if (v.depreciationMethod && v.depreciationMethod.length > 50) {
    throw invalid('상각 방법은 50자 이하여야 합니다.');
  }
  if (v.usefulLifeYears !== null) {
    if (!INT_RE.test(v.usefulLifeYears) || Number(v.usefulLifeYears) <= 0) {
      throw invalid('내용연수는 1 이상의 정수여야 합니다.');
    }
  }
  if (v.depreciationStartDate !== null) {
    if (!DATE_RE.test(v.depreciationStartDate)) {
      throw invalid('상각 시작일 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }
    if (v.depreciationStartDate < (v.acquisitionDate as string)) {
      throw invalid('상각 시작일은 취득일 이후여야 합니다.');
    }
  }
  if (v.useStatus !== '사용' && v.useStatus !== '미사용') {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
}

const RETURN_COLUMNS = `fixed_asset_id AS "fixedAssetId",
  asset_code AS "assetCode",
  asset_name AS "assetName",
  acquisition_cost AS "acquisitionCost",
  use_status AS "useStatus"`;

@Controller('api/v1')
export class FnSfr01101Controller {
  @Post('/fixed-assets')
  @HttpCode(200)
  async createFixedAsset(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_ASSET);
    const data = checks.inputOf(req.body);
    const assetCode = text(data['assetCode']);
    const assetNo = text(data['assetNo']);
    if (!assetCode || !assetNo) {
      throw invalid('필수 항목이 누락되었습니다: 자산코드, 자산번호');
    }
    if (assetCode.length > 50 || assetNo.length > 50) {
      throw invalid('자산코드와 자산번호는 50자 이하여야 합니다.');
    }
    const values: AssetValues = {
      assetName: text(data['assetName']),
      acquisitionDate: text(data['acquisitionDate']),
      acquisitionCost: text(data['acquisitionCost']),
      isDepreciable: boolOf(data['isDepreciable']),
      depreciationMethod: text(data['depreciationMethod']),
      usefulLifeYears: text(data['usefulLifeYears']),
      depreciationStartDate: text(data['depreciationStartDate']),
      useStatus: text(data['useStatus']) ?? DEFAULT_USE_STATUS,
    };
    validateAsset(values);
    return transaction(async (db) => {
      // 결정: 고정자산 코드는 중복되지 않아야 한다.
      const dup = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE asset_code = :assetCode',
        { assetCode },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ASSET_CODE_DUPLICATED', '이미 존재하는 고정자산 코드입니다.');
      }
      const rows = await db.query(
        `INSERT INTO fixed_asset (
          asset_code, asset_no, asset_name, acquisition_date, acquisition_cost,
          is_depreciable, depreciation_method, useful_life_years,
          depreciation_start_date, use_status, created_at, updated_at
        ) VALUES (
          :assetCode, :assetNo, :assetName, CAST(:acquisitionDate AS date),
          CAST(:acquisitionCost AS numeric), :isDepreciable, :depreciationMethod,
          CAST(:usefulLifeYears AS integer), CAST(:depreciationStartDate AS date),
          :useStatus, now(), now()
        ) RETURNING ${RETURN_COLUMNS}`,
        { assetCode, assetNo, ...values },
      );
      return rows[0];
    });
  }

  @Patch('/fixed-assets/:fixedAssetId')
  async updateFixedAsset(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_ASSET);
    const data = checks.inputOf(req.body);
    const idText = req.params['fixedAssetId'];
    if (!INT_RE.test(idText)) {
      throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '대상 고정자산을 찾을 수 없습니다.');
    }
    const has = (key: string): boolean => Object.prototype.hasOwnProperty.call(data, key);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT asset_name AS "assetName",
          to_char(acquisition_date, 'YYYY-MM-DD') AS "acquisitionDate",
          CAST(acquisition_cost AS text) AS "acquisitionCost",
          is_depreciable AS "isDepreciable",
          depreciation_method AS "depreciationMethod",
          CAST(useful_life_years AS text) AS "usefulLifeYears",
          to_char(depreciation_start_date, 'YYYY-MM-DD') AS "depreciationStartDate",
          use_status AS "useStatus"
        FROM fixed_asset
        WHERE fixed_asset_id = CAST(:id AS bigint)`,
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '대상 고정자산을 찾을 수 없습니다.');
      }
      const old = found[0];
      const merged: AssetValues = {
        assetName: has('assetName') ? text(data['assetName']) : old.assetName,
        acquisitionDate: has('acquisitionDate') ? text(data['acquisitionDate']) : old.acquisitionDate,
        acquisitionCost: has('acquisitionCost') ? text(data['acquisitionCost']) : old.acquisitionCost,
        isDepreciable: has('isDepreciable') ? boolOf(data['isDepreciable']) : old.isDepreciable,
        depreciationMethod: has('depreciationMethod') ? text(data['depreciationMethod']) : old.depreciationMethod,
        usefulLifeYears: has('usefulLifeYears') ? text(data['usefulLifeYears']) : old.usefulLifeYears,
        depreciationStartDate: has('depreciationStartDate') ? text(data['depreciationStartDate']) : old.depreciationStartDate,
        useStatus: has('useStatus') ? text(data['useStatus']) : old.useStatus,
      };
      validateAsset(merged);
      const rows = await db.query(
        `UPDATE fixed_asset SET
          asset_name = :assetName,
          acquisition_date = CAST(:acquisitionDate AS date),
          acquisition_cost = CAST(:acquisitionCost AS numeric),
          is_depreciable = :isDepreciable,
          depreciation_method = :depreciationMethod,
          useful_life_years = CAST(:usefulLifeYears AS integer),
          depreciation_start_date = CAST(:depreciationStartDate AS date),
          use_status = :useStatus,
          updated_at = now()
        WHERE fixed_asset_id = CAST(:id AS bigint)
        RETURNING ${RETURN_COLUMNS}`,
        { id: idText, ...merged },
      );
      return rows[0];
    });
  }

  @Get('/fixed-assets')
  async listFixedAssets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_ASSET, ROLE_ACCOUNTING);
    const query = checks.queryOf(req.query);
    const assetCode = text(query['assetCode']);
    const accountItemId = text(query['accountItemId']);
    if (accountItemId !== null && !INT_RE.test(accountItemId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 형식이 올바르지 않습니다.');
    }
    const pageText = text(query['page']) ?? '0';
    const sizeText = text(query['size']) ?? String(DEFAULT_SIZE);
    if (!INT_RE.test(pageText) || !INT_RE.test(sizeText) || Number(sizeText) < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기 형식이 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Number(sizeText), MAX_SIZE);
    return transaction(async (db) => {
      const where = `WHERE (CAST(:assetCode AS text) IS NULL OR asset_code = CAST(:assetCode AS text))
        AND (CAST(:accountItemId AS bigint) IS NULL OR account_item_id = CAST(:accountItemId AS bigint))`;
      const counted = await db.query(
        `SELECT COUNT(*) AS total FROM fixed_asset ${where}`,
        { assetCode, accountItemId },
      );
      const items = await db.query(
        `SELECT fixed_asset_id AS "fixedAssetId",
          asset_code AS "assetCode",
          asset_no AS "assetNo",
          asset_name AS "assetName",
          acquisition_date AS "acquisitionDate",
          acquisition_cost AS "acquisitionCost",
          depreciation_method AS "depreciationMethod",
          useful_life_years AS "usefulLifeYears",
          use_status AS "useStatus"
        FROM fixed_asset ${where}
        ORDER BY fixed_asset_id DESC
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { assetCode, accountItemId, size, offset: page * size },
      );
      return { items, page, size, total: Number(counted[0].total) };
    });
  }
}

