import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  Select,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

type DrawerState =
  | { kind: 'create' }
  | { kind: 'detail'; row: Row }
  | { kind: 'edit'; row: Row }
  | null;

const PAGE_SIZE = 20;

const STATUS_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

const DEPRECIABLE_OPTIONS: [string, string][] = [
  ['true', '예'],
  ['false', '아니오'],
];

function blank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function AssetForm({ role, row, onDone }: { role: string; row?: Row; onDone: (message: string) => void }) {
  const editing = row !== undefined;
  const [v, setV] = useState<Row>(
    row
      ? {
          assetName: row['assetName'] ?? '',
          acquisitionDate: row['acquisitionDate'] ? String(row['acquisitionDate']).slice(0, 10) : '',
          acquisitionCost: row['acquisitionCost'] ?? '',
          isDepreciable: '',
          depreciationMethod: row['depreciationMethod'] ?? '',
          usefulLifeYears: row['usefulLifeYears'] ?? '',
          depreciationStartDate: '',
          useStatus: row['useStatus'] ?? '사용',
        }
      : { useStatus: '사용' },
  );
  const set = (key: string) => (value: unknown) => setV({ ...v, [key]: value });

  const submit = async () => {
    const required: [string, string][] = editing
      ? [['assetName', '자산명'], ['acquisitionDate', '취득일'], ['acquisitionCost', '취득원가']]
      : [
          ['assetCode', '자산코드'],
          ['assetNo', '자산번호'],
          ['assetName', '자산명'],
          ['acquisitionDate', '취득일'],
          ['acquisitionCost', '취득원가'],
          ['isDepreciable', '상각 여부'],
        ];
    const missing = required.filter(([key]) => blank(v[key])).map(([, label]) => label);
    if (!editing && v['isDepreciable'] === 'true') {
      if (blank(v['depreciationMethod'])) missing.push('상각 방법');
      if (blank(v['usefulLifeYears'])) missing.push('내용연수');
      if (blank(v['depreciationStartDate'])) missing.push('상각 시작일');
    }
    if (missing.length > 0) {
      throw new Error('필수 항목을 입력하세요: ' + missing.join(', '));
    }
    const body: Row = {};
    Object.keys(v).forEach((key) => {
      if (blank(v[key])) return;
      body[key] = key === 'isDepreciable' ? v[key] === 'true' : v[key];
    });
    if (editing) {
      await call('PATCH', '/fixed-assets/' + String(row['fixedAssetId']), role, body);
      onDone('고정자산을 수정했습니다.');
    } else {
      await call('POST', '/fixed-assets', role, body);
      onDone('고정자산을 등록했습니다.');
    }
  };

  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '등록'}>
      {!editing && (
        <Field label='자산코드' required>
          <TextInput value={v['assetCode']} onChange={set('assetCode')} />
        </Field>
      )}
      {!editing && (
        <Field label='자산번호' required>
          <TextInput value={v['assetNo']} onChange={set('assetNo')} />
        </Field>
      )}
      <Field label='자산명' required wide>
        <TextInput value={v['assetName']} onChange={set('assetName')} />
      </Field>
      <Field label='취득일' required>
        <DateInput value={v['acquisitionDate']} onChange={set('acquisitionDate')} />
      </Field>
      <Field label='취득원가' required>
        <NumberInput value={v['acquisitionCost']} onChange={set('acquisitionCost')} />
      </Field>
      <Field label='상각 여부' required={!editing} hint={editing ? '바꾸지 않으면 기존 값을 유지합니다.' : undefined}>
        <Select
          value={v['isDepreciable']}
          onChange={set('isDepreciable')}
          options={DEPRECIABLE_OPTIONS}
          placeholder={editing ? '변경 안 함' : '선택'}
        />
      </Field>
      <Field label='상각 방법' hint='상각 대상이면 필수'>
        <TextInput value={v['depreciationMethod']} onChange={set('depreciationMethod')} />
      </Field>
      <Field label='내용연수' hint='상각 대상이면 필수 (년)'>
        <NumberInput value={v['usefulLifeYears']} onChange={set('usefulLifeYears')} />
      </Field>
      <Field label='상각 시작일' hint='상각 대상이면 필수'>
        <DateInput value={v['depreciationStartDate']} onChange={set('depreciationStartDate')} />
      </Field>
      <Field label='사용 여부'>
        <Select value={v['useStatus']} onChange={set('useStatus')} options={STATUS_OPTIONS} />
      </Field>
    </Form>
  );
}

export default function FnSfr01101Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({ assetCode: '', accountItemId: '' });
  const [applied, setApplied] = useState<Row>({ assetCode: '', accountItemId: '' });
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<DrawerState>(null);

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/fixed-assets', role, undefined, {
        assetCode: applied['assetCode'],
        accountItemId: applied['accountItemId'],
        page,
        size: PAGE_SIZE,
      }),
    [applied, page, role],
  );

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const usedCount = rows.filter((r) => r['useStatus'] === '사용').length;
  const unusedCount = rows.filter((r) => r['useStatus'] === '미사용').length;

  const done = (message: string) => {
    setDrawer(null);
    notify(message);
    list.reload();
  };

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>고정자산 현황</h2>
        <Tiles
          items={[
            ['전체 건수', <Num value={total} />],
            ['사용 (현재 쪽)', <Num value={usedCount} />],
            ['미사용 (현재 쪽)', <Num value={unusedCount} />],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>고정자산 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ ...draft });
          }}
          onReset={() => {
            const empty = { assetCode: '', accountItemId: '' };
            setDraft(empty);
            setApplied(empty);
            setPage(0);
          }}
        >
          <Field label='자산코드'>
            <TextInput value={draft['assetCode']} onChange={(x) => setDraft({ ...draft, assetCode: x })} />
          </Field>
          <Field label='계정과목'>
            <LookupSelect
              table='account_item'
              role={role}
              value={draft['accountItemId']}
              onChange={(x) => setDraft({ ...draft, accountItemId: x })}
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={() => setDrawer({ kind: 'create' })}>
            고정자산 등록
          </button>
        </Band>
        {list.error && <p>{list.error}</p>}
        <DataTable
          rows={rows}
          empty={list.loading ? '불러오는 중입니다.' : '등록된 고정자산이 없습니다.'}
          onRowClick={(row) => setDrawer({ kind: 'detail', row })}
          columns={[
            { key: 'assetCode', label: '자산코드' },
            { key: 'assetNo', label: '자산번호' },
            { key: 'assetName', label: '자산명' },
            { key: 'acquisitionDate', label: '취득일', render: (r) => <DateText value={r['acquisitionDate']} /> },
            { key: 'acquisitionCost', label: '취득원가', render: (r) => <Num value={r['acquisitionCost']} /> },
            { key: 'depreciationMethod', label: '상각 방법' },
            { key: 'usefulLifeYears', label: '내용연수', render: (r) => <Num value={r['usefulLifeYears']} /> },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
          ]}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>

      {drawer && drawer.kind === 'create' && (
        <Drawer title='고정자산 등록' onClose={() => setDrawer(null)}>
          <AssetForm role={role} onDone={done} />
        </Drawer>
      )}
      {drawer && drawer.kind === 'detail' && (
        <Drawer title='고정자산 상세' onClose={() => setDrawer(null)}>
          <Pairs
            items={[
              ['자산코드', String(drawer.row['assetCode'] ?? '')],
              ['자산번호', String(drawer.row['assetNo'] ?? '')],
              ['자산명', String(drawer.row['assetName'] ?? '')],
              ['취득일', <DateText value={drawer.row['acquisitionDate']} />],
              ['취득원가', <Num value={drawer.row['acquisitionCost']} />],
              ['상각 방법', String(drawer.row['depreciationMethod'] ?? '')],
              ['내용연수', <Num value={drawer.row['usefulLifeYears']} />],
              ['사용 여부', <Badge value={drawer.row['useStatus']} />],
            ]}
          />
          <button type='button' onClick={() => setDrawer({ kind: 'edit', row: drawer.row })}>
            수정
          </button>
        </Drawer>
      )}
      {drawer && drawer.kind === 'edit' && (
        <Drawer title='고정자산 수정' onClose={() => setDrawer(null)}>
          <AssetForm role={role} row={drawer.row} onDone={done} />
        </Drawer>
      )}
    </div>
  );
}
